// Retire temporary presentation shadows from the earlier web-only fix.
// The native layout now removes its own placeholder. Match exact generated bytes
// so original game files and customized profile resources remain intact.
const generated = [
  ['Data/textdata.cam', 'f5cbb50e01c78042366e287dac3db4af66db5bfcffe4a21935f91f6effda0898'],
  ['Data/mx_textdata.cam', 'f323ed5534b0cc76456ef06a39d95b9c1a02de33667ad3dcafd5986493605d0d'],
  ['DataMX/mx_textdata.cam', 'f323ed5534b0cc76456ef06a39d95b9c1a02de33667ad3dcafd5986493605d0d'],
];
const fileHash = async file => [...new Uint8Array(await crypto.subtle.digest('SHA-256', await file.arrayBuffer()))]
  .map(n => n.toString(16).padStart(2, '0')).join('');

export async function removeMenuTextShadows({profilePath, storage = navigator.storage, signal,
  digest = fileHash} = {}) {
  if (!/^majesty\/profile(?:\/[a-zA-Z0-9_-]{1,80})*$/.test(profilePath))
    throw Error('Invalid menu presentation profile');
  signal?.throwIfAborted();
  let profile = await storage.getDirectory();
  try {
    for (const part of profilePath.split('/')) profile = await profile.getDirectoryHandle(part);
  } catch (error) { if (error.name === 'NotFoundError') return 0; throw error; }
  let removed = 0;
  for (const [path, expected] of generated) {
    signal?.throwIfAborted();
    const [directory, name] = path.split('/');
    let parent, file;
    try {
      parent = await profile.getDirectoryHandle(directory);
      file = await (await parent.getFileHandle(name)).getFile();
    } catch (error) { if (error.name === 'NotFoundError') continue; throw error; }
    if (file.size > 1024 * 1024 || await digest(file) !== expected) continue;
    signal?.throwIfAborted();
    await parent.removeEntry(name);
    removed++;
  }
  return removed;
}
